(() => {
'use strict';
const D=window.DEMO;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,d=0)=>new Intl.NumberFormat('en-TH',{style:'currency',currency:'THB',currencyDisplay:'narrowSymbol',maximumFractionDigits:d}).format(n);
const short=n=>n>=1000000?`฿${Number((n/1000000).toFixed(2))}m`:n>=1000?`฿${Number((n/1000).toFixed(1))}k`:money(n);
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',wallet:'M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v11H5a3 3 0 0 1-3-3V6 M16 12h6v5h-6z M18 14.5h.01',arrows:'M4 7h15m-4-4 4 4-4 4 M20 17H5m4-4-4 4 4 4',bank:'m3 9 9-6 9 6H3 M5 10v8 M10 10v8 M14 10v8 M19 10v8 M3 21h18',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',building:'M4 21V5h10v16 M14 10h6v11 M8 9h2 M8 13h2 M8 17h2 M2 21h20',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',chart:'M3 3v18h18 M7 14l4-5 4 3 5-7',settings:'M9 3h6l1 4 4 1v8l-4 1-1 4H9l-1-4-4-1V8l4-1z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M4 12h16 m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',up:'M7 17 17 7 M7 7h10v10',plus:'M12 5v14 M5 12h14',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',check:'m5 12 4 4L19 6',shield:'m12 2 8 3v6c0 5-8 11-8 11S4 16 4 11V5z M8 12l3 3 5-6',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'M6 6l12 12 M18 6 6 18',logout:'M9 4H4v16h5 M9 12h12 m-5-5 5 5-5 5',menu:'M3 6h18 M3 12h18 M3 18h18',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M2 12h20 M12 2a18 18 0 0 1 0 20 18 18 0 0 1 0-20',briefcase:'M8 7V3h8v4 M3 7h18v14H3z M3 12a25 25 0 0 0 18 0 M10 12h4v4h-4z',lock:'M6 10V7a6 6 0 0 1 12 0v3 M4 10h16v12H4z M12 15v3',filter:'M4 7h16 M7 12h10 M10 17h4',cash:'M2 5h20v14H2z M16 12h2 M6 12h.01 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',card:'M2 5h20v14H2z M2 10h20 M6 15h4',external:'M14 3h7v7 M10 14 21 3 M10 3H3v18h18v-7',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const mark=`<span class="brandmark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8"><path d="M5 20V4h7a4 4 0 0 1 0 8H5m7 0a4 4 0 0 1 0 8H5"/></svg></span>`;
let saved={};try{saved=JSON.parse(localStorage.getItem('bahtbridge-v2')||'{}')}catch{}
const state={role:'sme',page:'overview',period:'6M',query:'',filter:'all',sort:'match',compare:[],vendorCompare:[],creditCategory:'all',advanced:{},...saved};
state.transactions=state.transactions||structuredClone(D.transactions);state.applications=state.applications||structuredClone(D.applications);state.business=state.business||structuredClone(D.business);state.sharing=state.sharing||{transactions:true,documents:true,profile:true};
state.query='';state.filter='all';state.compare=[];state.vendorCompare=[];state.creditCategory='all';state.advanced={};
const persist=()=>{try{localStorage.setItem('bahtbridge-v2',JSON.stringify(state))}catch{toast('Changes are available for this session. Browser storage is unavailable.')}};
const lender=id=>D.lenders.find(l=>l.id===id)||D.lenders[0];
const business=id=>id==='bloom'?{...D.businesses[0],...state.business}:D.businesses.find(b=>b.id===id)||D.businesses[0];
const myApps=()=>state.applications.filter(a=>state.role==='sme'?a.businessId==='bloom':a.lenderId==='northstar');
const statusTag=s=>`<span class="tag ${/Approved|Accepted|Completed|Verified|Active/.test(s)?'green':/Offer/.test(s)?'blue':/Declined|Withdrawn/.test(s)?'red':'amber'}">${esc(s)}</span>`;
const searchable=values=>values.flatMap(value=>[value,window.BBLocale?.t(value)||value]).join(' ').toLowerCase();
const initials=s=>s.split(/\s/).map(a=>a[0]).slice(0,2).join('').toUpperCase();
const btn=(label,action,ic='',cls='')=>`<button class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function go(page){state.page=page;state.query='';state.filter='all';state.creditCategory='all';state.advanced={};state.vendorCompare=[];persist();render();window.scrollTo({top:0});}
const navSME=[['overview','Overview','grid'],['transactions','Transactions','arrows'],['marketplace','Credit marketplace','bank'],['applications','Applications','file'],['suppliers','Suppliers','users'],['profile','Business profile','building']];
const navLender=[['overview','Overview','grid'],['businesses','Discover vendors','building'],['marketplace','Market comparison','arrows'],['applications','Applications','file'],['portfolio','Portfolio','briefcase'],['suppliers','Supplier network','users'],['profile','Lender profile','bank']];
function render(){if(!window.BahtbridgeAccess.active){window.BahtbridgeAccess.render();return;}const nav=state.role==='sme'?navSME:navLender;const current=nav.find(n=>n[0]===state.page);if(!current&&state.page!=='settings')state.page='overview';const count=myApps().filter(a=>a.status==='Under review').length;
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#" class="brand" data-action="nav:overview">${mark}bahtbridge<span style="color:#5c8cff">.</span></a><div class="workspace"><span class="avatar">${state.role==='sme'?'SP':'S'}</span><div><strong>${state.role==='sme'?'Siam Pantry':'Siam Capital'}</strong><span class="tiny muted">${state.role==='sme'?'Business account':'Lender workspace'}</span></div>${icon('down')}</div><div class="navlabel">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(n=>`<button class="${state.page===n[0]?'active':''}" data-action="nav:${n[0]}">${icon(n[2])}${n[1]}${n[0]==='applications'&&count?`<span class="navbadge">${count}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-card">${icon('globe')}<h3 style="font-size:12px">Business and lending workspaces</h3><p>Explore the full experience as a business owner or credit provider.</p><button data-action="role:${state.role==='sme'?'lender':'sme'}">Switch to ${state.role==='sme'?'lender':'business'} view ${icon('arrow')}</button></div><nav class="nav"><button data-action="help">${icon('help')}Help & support</button><button data-action="nav:settings" class="${state.page==='settings'?'active':''}">${icon('settings')}Settings</button><button data-access="signout">${icon('logout')}Sign out</button></nav><div class="sidebar-foot"><span class="avatar">${state.role==='sme'?'NC':'PW'}</span><div><strong style="font-size:11px;font-weight:500">${state.role==='sme'?esc(state.business.owner):'Preecha Wattanakul'}</strong><p class="tiny muted" style="margin-top:4px">${state.role==='sme'?'Vendor':'Investment manager'}</p></div><button class="iconbtn" data-action="nav:settings" aria-label="Account settings">${icon('down')}</button></div></div></aside><main class="main"><header class="topbar"><button class="iconbtn mobile-toggle" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span class="mobile-brand">bahtbridge.</span><div class="breadcrumb">Workspace ${icon('chevron')}<b>${esc(current?.[1]||'Settings')}</b></div><div class="top-actions"><button type="button" class="language-switch" data-locale-toggle data-no-translate aria-label="Switch to Thai"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a17 17 0 0 1 0 18 17 17 0 0 1 0-18"/></svg><span lang="th">ไทย</span></button><div class="role-switch" aria-label="Workspace role"><button data-action="role:sme" class="${state.role==='sme'?'selected':''}">Vendor</button><button data-action="role:lender" class="${state.role==='lender'?'selected':''}">Lender</button></div><div class="divider"></div><button class="iconbtn" data-action="notifications" aria-label="Notifications">${icon('bell')}<i class="notif-dot"></i></button><span class="avatar" style="border-radius:50%">${state.role==='sme'?'NC':'PW'}</span></div></header><div class="content" id="content">${pageContent()}<footer class="footer"><span>${icon('lock')}Demonstration workspace · All businesses and offers are fictional</span><span>Bahtbridge © 2026 &nbsp; · &nbsp; THB</span></footer></div></main></div>${state.vendorCompare.length?`<div class="compare-bar"><span>${state.vendorCompare.length} vendors selected</span>${btn('Compare vendors','compare-vendors','arrows','primary sm')}${btn('Clear','clear-vendors','','sm ghost')}</div>`:''}${state.compare.length?`<div class="compare-bar"><span>${state.compare.length} provider${state.compare.length>1?'s':''} selected</span>${btn('Compare providers','compare','arrows','primary sm')}${btn('Clear','clear-compare','','sm ghost')}</div>`:''}`;
if(state.page==='transactions'||state.page==='businesses'||state.page==='marketplace'||state.page==='applications')filterResults();
}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="buttons">${actions}</div></div>`}
function stat(label,value,change,detail,ic='wallet'){return `<div class="stat"><div class="stat-top">${label}${icon(ic)}</div><div class="number">${value}</div><div class="stat-bottom">${change?`<span class="positive">${icon('up')}${change}</span>`:''}<span>${detail}</span></div></div>`}
function chart(title='Cash flow overview',subtitle='Money received and business expenses',scale=1){
const period=state.period,totals=monthlyTotals();
const labels=period==='1M'?['4 Nov','7 Nov','10 Nov','13 Nov','16 Nov','17 Nov']:period==='3M'?['Sep','Oct','Nov']:['Jun','Jul','Aug','Sep','Oct','Nov'];
let incoming=period==='3M'?[412000,410230,totals.income]:[321000,389000,365000,412000,410230,totals.income];
let outgoing=period==='3M'?[298000,300000,totals.expense]:[251200,279000,256000,298000,300000,totals.expense];
if(period==='1M'){const dates=['04','07','10','13','16','17'];const sum=(type,day)=>state.transactions.filter(t=>t.type===type&&t.date>='2026-11-01'&&t.date<='2026-11-'+day).reduce((a,t)=>a+t.amount,0);incoming=dates.map(d=>sum('income',d));outgoing=dates.map(d=>sum('expense',d));}
incoming=incoming.map(v=>v*scale);outgoing=outgoing.map(v=>v*scale);const max=Math.ceil(Math.max(...incoming,...outgoing)/10000)*10000||10000;
const x=i=>70+i*510/(labels.length-1),y=v=>175-v/max*140,points=arr=>arr.map((v,i)=>`${x(i)},${y(v)}`).join(' ');
return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${subtitle}</p></div><div class="chart-total"><div class="segment">${['1M','3M','6M'].map(p=>`<button data-action="period:${p}" class="${period===p?'selected':''}">${p}</button>`).join('')}</div></div></div><div class="chart-legend"><span><i class="dot"></i>Money in</span><span><i class="dot teal"></i>Money out</span><span style="margin-left:auto;color:#5b7194">${period==='1M'?'Nov · Recorded totals':'2026 · Illustrative history'}</span></div><div class="cash-chart"><svg viewBox="0 0 620 210" role="img" aria-label="Cash flow chart for ${period}. Total money in ${money(incoming.at(-1))}, total money out ${money(outgoing.at(-1))}."><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3c7bfa" stop-opacity=".22"/><stop offset="100%" stop-color="#3c7bfa" stop-opacity="0"/></linearGradient></defs>${[1,.75,.5,.25].map(v=>`<line x1="55" y1="${y(max*v)}" x2="595" y2="${y(max*v)}" class="chart-grid"/><text x="3" y="${y(max*v)+3}" class="chart-label">${short(max*v)}</text>`).join('')}<polygon points="70,176 ${points(incoming)} 580,176" fill="url(#chartFill)"/><polyline points="${points(outgoing)}" fill="none" stroke="#4b9ba9" stroke-width="2" stroke-linejoin="round"/><polyline points="${points(incoming)}" fill="none" stroke="#6495ff" stroke-width="2.7" stroke-linejoin="round"/>${incoming.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3.5" fill="#7ba6ff" stroke="#152139" stroke-width="2"><title>${labels[i]}: ${money(v)}</title></circle>`).join('')}${labels.map((m,i)=>`<text x="${x(i)}" y="200" class="chart-label" text-anchor="middle">${m}</text>`).join('')}</svg></div></section>`;
}
function readiness(score=82){return `<section class="panel readiness"><div style="display:flex;align-items:center;justify-content:space-between"><span class="eyebrow">Credit readiness</span>${icon('shield')}</div><div class="score-ring"><svg viewBox="0 0 170 134"><path d="M28 108a64 64 0 1 1 114 0" fill="none" stroke="#25364f" stroke-width="8" stroke-linecap="round"/><path d="M28 108a64 64 0 1 1 114 0" fill="none" stroke="#5c91fc" stroke-width="8" stroke-linecap="round" pathLength="100" stroke-dasharray="${score} 100"/></svg><div class="score-text"><strong>${score}</strong><small>/ 100</small></div></div><p class="score-caption">Strong financial profile</p><div class="checkline">${icon('check')}Business details complete</div><div class="checkline">${icon('check')}Transaction history recorded</div><div class="checkline">${icon('check')}Documents available</div>${btn('View business profile','nav:profile','arrow','full sm')}</section>`}
function lenderCard(l,compare=false){const amount=Number(state.advanced.amount)||Math.min(l.max,Math.max(l.min,250000));const months=Math.max(l.termMin,Math.min(l.termMax,12));const estimate=payment(amount,l.rate,months);return `<article class="lender-card"><div class="lender-top"><span class="company-mark" style="background:${l.colour}33;color:#b3ceff">${l.short}</span><span class="match">${l.match}% sample match</span></div><h3>${esc(l.name)}</h3><p>${l.type}</p><div class="lender-rate"><strong>${l.rate.toFixed(1)}%</strong><span>indicative annual interest</span></div><div class="provider-summary"><span class="tag blue">${esc(l.badge||l.decision)}</span><span class="tag">${l.collateral}</span></div><div class="lender-facts"><span>Funding available<strong>${short(l.min)} to ${short(l.max)}</strong></span><span>Repayment term<strong>${l.term.replace(/[–-]/g,' to ')}</strong></span></div><div class="estimate-line">${months>=1&&l.type!=='Credit line'?`Example: <strong>${money(estimate)} / month</strong> on ${short(amount)} over ${months} months`:l.type==='Credit line'?`Revolving facility · Interest on funds drawn`:`Repayment period: ${esc(l.term.replace(/[–-]/g,' to '))}`}<br>Arrangement fee: ${l.fee}% · ${l.minTradingMonths} months minimum trading<br><span class="tiny muted">Repayment examples exclude fees.</span></div>${btn('View funding option',`lender:${l.id}`,'arrow','full')}${compare?`<label class="compare-check"><input type="checkbox" data-compare="${l.id}" ${state.compare.includes(l.id)?'checked':''}>Compare this lender</label>`:''}</article>`}

function transactionTable(rows,allow=true){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Date</th><th>Category</th><th>Method</th><th style="text-align:right">Amount</th><th>Status</th></tr></thead><tbody>${rows.map(t=>`<tr><td><div class="entity"><span class="avatar">${icon(t.type==='income'?'down':'up')}</span><div><strong>${esc(t.counterparty)}</strong><p>${esc(t.id)}</p></div></div></td><td>${date(t.date)}</td><td>${esc(t.category)}</td><td>${icon(t.method==='Cash'?'cash':t.method==='Card'?'card':'bank')} <span style="margin-left:5px">${t.method}</span></td><td style="text-align:right" class="amount ${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'}${money(t.amount,2)}</td><td>${statusTag(t.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('No transactions found','Try a different search or add a transaction.','arrows',allow?btn('Add transaction','add-transaction','plus','primary'):'')}
function empty(title,desc,ic='search',action=''){return `<div class="empty">${icon(ic)}<h3>${title}</h3><p>${desc}</p>${action}</div>`}
function monthlyTotals(){const extra=state.transactions.filter(t=>!D.transactions.some(x=>x.id===t.id));return {income:486500+extra.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0),expense:312400+extra.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0),balance:284500+extra.reduce((s,t)=>s+(t.type==='income'?t.amount:-t.amount),0)}}
function overview(){if(state.role==='lender')return lenderOverview();const extra=state.transactions.filter(t=>!D.transactions.some(x=>x.id===t.id));const added=extra.reduce((s,t)=>s+(t.type==='income'?t.amount:-t.amount),0);return `${heading('Your business overview','Welcome back, Narin. Here is where your business stands.',btn('Export report','export-report','download')+btn('Add transaction','add-transaction','plus','primary'))}<section class="hero"><div><div class="eyebrow">A clearer path to business credit</div><h2>Finance for your next business investment.</h2><p>Your transaction history helps providers understand your business.<br>Explore funding options that fit your plans.</p></div><div class="hero-amount"><div class="small">Indicative funding available</div><div class="number">฿750,000</div><div class="small">Across 10 credit providers</div></div>${btn('Explore credit','nav:marketplace','arrow')}</section><div class="stats">${stat('Available balance',money(state.business.balance+added),'12.8%','vs last month','wallet')}${stat('Money in this month',money(486500+extra.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0)),'18.6%','vs last month','down')}${stat('Money out this month',money(312400+extra.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0)),'4.2%','vs last month','up')}${stat('Active applications',myApps().filter(a=>!['Declined','Withdrawn'].includes(a.status)).length,'',`${myApps().filter(a=>a.status==='Offer received').length} offer available`,'file')}</div><div class="grid-main">${chart()}${readiness(state.business.score)}</div><div class="section-heading"><div><h2>Credit options for your business</h2><p>Selected using your business profile and funding needs</p></div><button class="textbtn" data-action="nav:marketplace">View all providers ${icon('arrow')}</button></div><div class="lender-grid preview">${D.lenders.slice(0,3).map(l=>lenderCard(l)).join('')}</div><section class="panel table-section"><div class="panel-head"><div><h2>Recent transactions</h2><p>Your latest business activity, in one place</p></div><button class="textbtn" data-action="nav:transactions">View all ${icon('arrow')}</button></div>${transactionTable(state.transactions.slice(0,5))}</section>`}
function lenderOverview(){const apps=myApps();const funded=apps.filter(a=>a.status==='Approved'||a.status==='Accepted');return `${heading('Your lending overview','Welcome back, Preecha. Review opportunities across your portfolio.',btn('Export report','export-report','download')+btn('Discover businesses','nav:businesses','arrow','primary'))}<section class="hero"><div><div class="eyebrow">Business lending, with a clearer view</div><h2>Review businesses with clear financial context.</h2><p>Review business cash flow, recorded transactions and funding needs.<br>Find your next opportunity with the information that matters.</p></div><div class="hero-amount"><div class="small">Vendors seeking finance</div><div class="number">10</div><div class="small">Across 6 business sectors</div></div>${btn('Review applications','nav:applications','arrow')}</section><div class="stats">${stat('Capital deployed',money(funded.reduce((s,a)=>s+a.amount,0)),'','In this demonstration','briefcase')}${stat('Applications to review',apps.filter(a=>a.status==='Under review').length,'','Awaiting your decision','file')}${stat('Available vendors',D.businesses.length,'','Profiles available to review','building')}${stat('Average readiness',Math.round(D.businesses.reduce((sum,b)=>sum+b.score,0)/D.businesses.length)+' / 100','','Across available businesses','shield')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Funding activity</h2><p>Illustrative monthly capital deployment</p></div><span class="tag blue">Last 6 months</span></div><div class="panel-body"><div class="bar-chart">${[35,47,42,62,77,92].map((v,i)=>`<div class="bar" style="height:${v}%"><span>${['Jun','Jul','Aug','Sep','Oct','Nov'][i]}</span><title>${money(v*1500)}</title></div>`).join('')}</div><div class="chart-legend" style="margin:25px 0 3px"><span><i class="dot"></i>Capital deployed</span><span class="muted" style="margin-left:auto">Illustrative portfolio history</span></div></div></section><section class="panel"><div class="panel-head"><h2>Portfolio composition</h2></div><div class="panel-body"><div class="number" style="font-size:30px">${money(funded.reduce((s,a)=>s+a.amount,0))}</div><p class="small muted" style="margin-top:8px">Approved and accepted applications</p><div class="allocation">${['45','25','20','10'].map(v=>`<span style="width:${v}%"></span>`).join('')}</div>${['Wholesale','Food & beverage','Creative services','Other sectors'].map((v,i)=>`<div class="detail-row small"><span>${v}</span><strong>${[45,25,20,10][i]}%</strong></div>`).join('')}<p class="tiny muted" style="margin-top:14px">Illustrative sector allocation</p></div></section></div><section class="panel table-section"><div class="panel-head"><div><h2>Applications requiring attention</h2><p>Review the latest funding requests</p></div><button class="textbtn" data-action="nav:applications">View all ${icon('arrow')}</button></div><div style="height:20px"></div>${applicationTable(apps.filter(a=>a.status!=='Approved'&&a.status!=='Accepted'))}</section><div class="section-heading"><div><h2>Businesses to explore</h2><p>Funding requests with detailed business profiles</p></div><button class="textbtn" data-action="nav:businesses">View all businesses ${icon('arrow')}</button></div><div class="business-grid">${D.businesses.slice(0,3).map(b=>businessCard(b)).join('')}</div>`}
function toolbar(placeholder,options='',extra=''){return `<div class="toolbar"><div class="search">${icon('search')}<input id="search-input" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(state.query)}"></div><div class="filter-group">${options?`<select id="filter-input" aria-label="Filter results">${options}</select>`:''}${extra}</div></div>`}
function transactions(){return `${heading('Transactions','Record every payment. Build a complete picture of your business.',btn('Export CSV','export-transactions','download')+btn('Add transaction','add-transaction','plus','primary'))}<div class="notice">${icon('info')}Cash entries are records of payments you have received or made. Adding a record does not move money.</div><div class="stats">${stat('Recorded income',money(state.transactions.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0)),'','All recorded entries','down')}${stat('Recorded expenses',money(state.transactions.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0)),'','All recorded entries','up')}${stat('Cash recorded',money(state.transactions.filter(t=>t.method==='Cash').reduce((s,t)=>s+t.amount,0)),'','Across income and expenses','cash')}${stat('Total transactions',state.transactions.length,'','All payment methods','arrows')}</div>${toolbar('Search transactions or categories','<option value="all">All transactions</option><option value="income">Money in</option><option value="expense">Money out</option><option value="Cash">Cash payments</option><option value="Card">Card payments</option><option value="Bank transfer">Bank transfers</option>')}<div class="count" id="results-count"></div><section class="panel" id="results"></section>`}

function filterField(label,id,options){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div>`}
function fundingChips(){return `<div class="funding-chips" aria-label="Funding categories">${BBFilters.categoryLabels.map(([value,label])=>`<button class="funding-chip ${state.creditCategory===value?'active':''}" data-action="category:${value}" aria-pressed="${state.creditCategory===value}">${label}</button>`).join('')}</div>`}
function discoveryFilters(isVendor=false){const all=[['all','Any term'],['short','Short term · Up to 12 months'],['long','Long term · Over 12 months']];return `<section class="discovery-filters"><div class="filter-title"><h2>${icon('filter')}${isVendor?'Find the right vendor':'Find the right funding'}</h2><button class="textbtn" data-action="reset-filters">Reset filters</button></div>${fundingChips()}<div class="discovery-grid">${isVendor?filterField('Business sector','filter-input',[['all','All sectors'],...[...new Set(D.businesses.map(b=>b.sector))].map(v=>[v,v])])+filterField('Minimum readiness score','risk-input',[['all','All verified profiles'],['85','85 and above'],['90','90 and above']])+filterField('Minimum monthly revenue','revenue-filter',[['','Any revenue'],['250000','฿250,000'],['500000','฿500,000'],['750000','฿750,000']])+filterField('Maximum funding request','vendor-amount-filter',[['','Any amount'],['200000','Up to ฿200,000'],['350000','Up to ฿350,000'],['500000','Up to ฿500,000']]):filterField('Finance product','filter-input',[['all','All finance products'],...D.lenders.map(l=>l.type).filter((v,i,a)=>a.indexOf(v)===i).map(v=>[v,v])])+`<div class="field"><label for="amount-filter">Amount required (฿)</label><input id="amount-filter" type="number" min="0" max="100000000" step="1000" placeholder="For example, 250000" value="${esc(state.advanced.amount||'')}"></div>`+filterField('Maximum annual interest','rate-filter',[['','Any annual rate'],['8','Up to 8%'],['10','Up to 10%'],['12','Up to 12%'],['15','Up to 15%']])+filterField('Security','collateral-filter',[['all','Any security'],['Unsecured','Unsecured'],['Secured','Secured']])}${filterField('Funding term','term-filter',all)}${filterField(isVendor?'Funding urgency':'Decision time','speed-filter',[['','Any decision time'],['1','Instant · Within 1 hour'],['4','Within 4 hours'],['24','Within 24 hours'],['48','Within 48 hours']])}${isVendor?filterField('Minimum trading history','trading-filter',[['','Any trading history'],['24','24 months'],['36','36 months'],['48','48 months']])+filterField('On time payment record','payments-filter',[['','All payment records'],['97','97% and above'],['99','99% and above']]):filterField('Sort funding options','sort-input',[['match','Best profile match'],['rate','Lowest annual rate'],['speed','Fastest decision'],['max','Highest funding limit']])+`<div class="field"><label>Market coverage</label><div class="coverage-label">${D.lenders.length} sample lenders · THB only</div></div>`}</div></section>`}

function marketplace(){const isLender=state.role==='lender';return `${heading(isLender?'Market comparison':'Find business finance',isLender?'Compare funding products, indicative annual rates and terms across the sample market.':'Compare Thai baht funding options for your business.',btn('Your applications','nav:applications','file'))}${discoveryFilters()}<div class="toolbar market-toolbar"><div class="search">${icon('search')}<input id="search-input" type="search" placeholder="Search lenders or finance products" aria-label="Search lenders or finance products" value="${esc(state.query)}"></div><div class="count" id="results-count"></div></div><div class="lender-grid" id="results"></div><div class="notice" style="margin-top:23px">${icon('info')}All providers and indicative annual rates are sample data. Instant and 24 hour filters describe illustrative decision times, not guaranteed fund transfers.</div>`}

function businessCard(b){return `<article class="panel business-card"><div class="profile-header"><span class="company-mark">${b.initials}</span><div><h2>${esc(b.name)}</h2><p>${esc(b.sector)} · ${esc(b.location.split(',')[0])}</p></div></div><p class="small muted" style="line-height:1.8;min-height:43px">${esc(b.description)}</p><div class="vendor-facts"><div><span>Monthly revenue</span><strong>${money(b.revenue)}</strong></div><div><span>Funding requested</span><strong>${money(b.requested)}</strong></div><div><span>Funding product</span><strong>${esc(b.fundingType)}</strong></div><div><span>Trading history</span><strong>${b.tradingMonths} months</strong></div></div><div class="top-score"><span>Sample credit readiness</span><strong>${b.score} / 100</strong></div><div class="progress"><span style="width:${b.score}%"></span></div><div class="vendor-proof">${icon('shield')}${b.paymentPerformance}% on time payments · Verified sample profile</div>${btn('Review vendor',`business:${b.id}`,'arrow','full')}<label class="comparison-select"><input type="checkbox" data-vendor-compare="${b.id}" ${state.vendorCompare.includes(b.id)?'checked':''}>Add vendor to comparison</label></article>`}

function businesses(){return `${heading('Discover vendors','Explore verified sample vendors with consistent revenue and strong payment records.',btn('Export directory','export-businesses','download'))}${discoveryFilters(true)}<div class="toolbar market-toolbar"><div class="search">${icon('search')}<input id="search-input" type="search" placeholder="Search vendors, sectors or Thai cities" aria-label="Search vendors, sectors or Thai cities" value="${esc(state.query)}"></div><select id="vendor-sort" aria-label="Sort vendors"><option value="score">Highest readiness score</option><option value="revenue">Highest monthly revenue</option><option value="requested">Largest funding request</option><option value="growth">Highest revenue growth</option></select><div class="count" id="results-count"></div></div><div class="business-grid" id="results"></div><div class="notice" style="margin-top:23px">${icon('lock')}All vendors are fictional Thai businesses. Financial records are sample data provided to demonstrate a lending review, not real credit assessments.</div>`}

function applicationTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>${state.role==='sme'?'Credit provider':'Business'}</th><th>Application</th><th>Amount</th><th>Purpose</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(a=>{const b=business(a.businessId),l=lender(a.lenderId);return `<tr><td><div class="entity"><span class="avatar">${state.role==='sme'?l.short:b.initials}</span><strong>${esc(state.role==='sme'?l.name:b.name)}</strong></div></td><td>${esc(a.id)}</td><td class="amount">${money(a.amount)}</td><td>${esc(a.purpose)}</td><td>${date(a.date)}</td><td>${statusTag(a.status)}</td><td>${btn('View',`application:${a.id}`,'chevron','sm ghost')}</td></tr>`}).join('')}</tbody></table></div>`:empty('No applications here','Applications matching this view will appear here.','file',state.role==='sme'?btn('Explore providers','nav:marketplace','arrow','primary'):btn('Discover businesses','nav:businesses','arrow','primary'))}
function applications(){return `${heading('Applications',state.role==='sme'?'Track your funding requests and review offers from providers.':'Review funding requests and manage your decisions.',state.role==='sme'?btn('Find credit','nav:marketplace','plus','primary'):btn('Discover businesses','nav:businesses','arrow','primary'))}<div class="stats">${stat('Total applications',myApps().length,'','In your workspace','file')}${stat('Under review',myApps().filter(a=>a.status==='Under review').length,'','Awaiting a decision','clock')}${stat('Offers available',myApps().filter(a=>a.status==='Offer received').length,'','Ready for review','bank')}${stat('Approved funding',money(myApps().filter(a=>['Approved','Accepted'].includes(a.status)).reduce((s,a)=>s+a.amount,0)),'','Approved and accepted','check')}</div>${toolbar('Search applications or businesses','<option value="all">All statuses</option>'+['Under review','Offer received','Approved','Accepted','Information requested','Declined','Withdrawn'].map(v=>`<option>${v}</option>`).join(''))}<section class="panel" id="results"></section>`}
const suppliers=[{name:'Chao Phraya Produce',initials:'GP',type:'Fresh produce',terms:'30 days',outstanding:6950.0,volume:42800.0,status:'Verified',businessId:'greenfield'},{name:'Sukhothai Flour Supply',initials:'LF',type:'Bakery ingredients',terms:'30 days',outstanding:12600.0,volume:75600.0,status:'Verified'},{name:'Lotus Packaging',initials:'PP',type:'Packaging',terms:'14 days',outstanding:3684.0,volume:22100.0,status:'Verified'},{name:'Thai Bright Energy',initials:'BE',type:'Utilities',terms:'Monthly',outstanding:3126.0,volume:18750.0,status:'Verified'}];
function supplierPage(){return `${heading(state.role==='sme'?'Your supplier network':'Supplier network',state.role==='sme'?'Manage supplier relationships and explore credit for business purchases.':'Review supplier relationships and trading activity across businesses.',state.role==='sme'?btn('Explore supplier credit','supplier-credit','bank','primary'):'')}<div class="stats">${stat('Active suppliers','4','','Recorded trading relationships','users')}${stat('Trading volume',money(159250),'','Illustrative last 6 months','arrows')}${stat('Outstanding invoices',money(26360),'','Illustrative current balance','file')}${stat('Average payment term','26 days','','Across supplier agreements','clock')}</div><section class="panel"><div class="panel-head" style="padding-bottom:20px"><div><h2>Supplier relationships</h2><p>Illustrative invoices and payment terms</p></div></div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Category</th><th>Payment terms</th><th>Trading volume</th><th>Outstanding</th><th>Profile</th><th></th></tr></thead><tbody>${suppliers.map((s,i)=>`<tr><td><div class="entity"><span class="avatar">${s.initials}</span><strong>${s.name}</strong></div></td><td>${s.type}</td><td>${s.terms}</td><td class="amount">${money(s.volume)}</td><td class="amount">${money(s.outstanding,2)}</td><td>${statusTag(s.status)}</td><td>${btn('Details',`supplier:${i}`,'chevron','sm ghost')}</td></tr>`).join('')}</tbody></table></div></section><div class="section-heading"><div><h2>Credit for your supply chain</h2><p>Explore finance for supplier payments and outstanding invoices</p></div></div><div class="lender-grid">${D.lenders.slice(4).map(l=>lenderCard(l)).join('')}</div>`}
function documents(businessId='bloom'){return ['Business registration','Bank statements','Management accounts'].map((name,i)=>`<div class="doc">${icon('file')}<div><h4 style="font-size:12px;font-weight:450">${name}</h4><p>Sample document · Updated 12 Nov 2026</p></div>${statusTag('Available')}${btn('Preview',`document:${i}:${businessId}`,'external','sm ghost')}</div>`).join('')}
function profile(){if(state.role==='lender')return `${heading('Lender profile','The provider information businesses see on the marketplace.',btn('Edit profile','edit-lender','settings'))}<div class="two-col"><section class="panel"><div class="panel-body"><div class="profile-header"><span class="company-mark large">S</span><div><h2>Siam Capital</h2><p>Business lending · Thailand</p></div></div><p class="small muted" style="line-height:1.9">${esc(lender('northstar').description)}</p><div class="detail-list">${detail('Product','Business loan')}${detail('Funding range','฿100,000 to ฿1,500,000')}${detail('Indicative annual rate',lender('northstar').rate+'%')}${detail('Loan terms','12 to 36 months')}${detail('Typical decision','Within 24 hours')}${detail('Contact','business@siamcapital.example')}</div></div></section><section class="panel"><div class="panel-head"><h2>Lending criteria</h2></div><div class="panel-body">${detail('Trading history','At least '+lender('northstar').minTradingMonths+' months')}${detail('Annual revenue','From ฿1,000,000')}${detail('Business location','Thailand')}${detail('Sectors','All eligible sectors')}<div class="notice" style="margin:18px 0 0">${icon('info')}This is a fictional provider profile for demonstration.</div></div></section></div>`;const b=state.business;return `${heading('Business profile','Keep your details current and control what providers can review.',btn('Edit profile','edit-profile','settings','primary'))}<div class="two-col"><section class="panel"><div class="panel-body"><div class="profile-header"><span class="company-mark large">SP</span><div><h2>${esc(b.name)}</h2><p>${esc(b.sector)} · ${esc(b.location)}</p></div></div>${statusTag('Verified')}<p class="small muted" style="line-height:1.9;margin:18px 0">${esc(b.description)}</p>${detail('Vendor',esc(b.owner))}${detail('Established',b.founded)}${detail('Employees',b.employees)}${detail('Registration',b.registration)}${detail('Email',esc(b.email))}${detail('Address',esc(b.address))}</div></section><div><section class="panel"><div class="panel-head"><h2>Profile completeness</h2><span class="tag blue">100%</span></div><div class="panel-body"><div class="progress"><span style="width:100%"></span></div>${['Business details','Transaction history','Supporting documents','Funding requirements'].map(v=>`<div class="checkline">${icon('check')}${v}</div>`).join('')}<p class="tiny muted" style="margin-top:19px;line-height:1.7">Readiness scores are illustrative and do not guarantee credit approval.</p></div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Data sharing</h2>${icon('lock')}</div><div class="panel-body"><p class="small muted" style="line-height:1.9">Providers you apply to can review the information you choose to share.</p>${btn('Manage permissions','nav:settings','shield','full sm')}</div></section></div></div><section class="panel table-section"><div class="panel-head"><div><h2>Business documents</h2><p>Sample documents included for the demonstration</p></div>${btn('Add document','add-document','plus','sm')}</div><div class="panel-body">${documents()}${(state.documents||[]).map(d=>`<div class="doc">${icon('file')}<div><h4 class="small">${esc(d.name)}</h4><p>Demo record only · No file uploaded</p></div>${statusTag('Recorded')}</div>`).join('')}</div></section>`}
function detail(k,v){return `<div class="detail-row"><span>${k}</span><strong>${v}</strong></div>`}
function portfolio(){const apps=myApps().filter(a=>['Approved','Accepted'].includes(a.status));return `${heading('Portfolio','Monitor approved facilities and the businesses you support.',btn('Export portfolio','export-portfolio','download'))}<div class="stats">${stat('Capital deployed',money(apps.reduce((s,a)=>s+a.amount,0)),'','Approved and accepted','briefcase')}${stat('Active facilities',apps.length,'','Current facilities','bank')}${stat('Illustrative annual yield','7.9%','','Before fees or losses','chart')}${stat('Repayment history','100%','','Illustrative sample history','check')}</div><section class="panel"><div class="panel-head" style="padding-bottom:20px"><h2>Active facilities</h2></div>${applicationTable(apps)}</section><div class="notice" style="margin-top:20px">${icon('info')}Accepting an offer updates this demo portfolio. No funds are transferred and no credit agreement is created.</div>`}
function settings(){if(state.role==='lender')return `${heading('Settings','Manage your lending workspace.')}<div class="two-col"><section class="panel"><div class="panel-head"><h2>Business data access</h2>${icon('lock')}</div><div class="panel-body"><p class="small muted" style="line-height:1.9">Businesses control access to their detailed profiles, transaction records and documents. Your workspace reflects their current sharing preferences. You cannot change a business permission.</p>${detail('Workspace','Siam Capital')}${detail('User','Preecha Wattanakul')}${detail('Access','Selected applicant records')}${btn('Review provider details','nav:profile','bank','full')}</div></section><section class="panel"><div class="panel-head"><h2>Demonstration controls</h2></div><div class="panel-body"><p class="small muted" style="line-height:1.9;margin-bottom:20px">Switch to the business workspace to manage data permissions. Demo activity is stored in this browser.</p>${btn('Switch to vendor','role:sme','arrows','full')}${btn('Reset demonstration','confirm-reset','settings','full ghost')}</div></section></div>`;return `${heading('Settings','Manage your workspace and sharing preferences.')}<div class="two-col"><section class="panel"><div class="panel-head"><h2>Data permissions</h2>${icon('shield')}</div><div class="panel-body"><p class="small muted" style="line-height:1.9;margin-bottom:9px">These controls apply to Siam Pantry. Changes are reflected when providers review your profile.</p>${[['profile','Business profile','Share your detailed business description with selected providers. Directory summaries remain visible.'],['transactions','Transaction history','Share recorded transactions with your selected providers.'],['documents','Supporting documents','Allow your selected providers to preview sample documents.']].map(([key,title,desc])=>`<label class="switchline"><div><h4>${title}</h4><p>${desc}</p></div><input type="checkbox" data-setting="${key}" ${state.sharing[key]?'checked':''} aria-label="${title}"></label>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Demonstration workspace</h2></div><div class="panel-body">${detail('Current role',state.role==='sme'?'Vendor':'Credit provider')}${detail('Currency','THB')}${detail('Data storage','This browser only')}<p class="small muted" style="line-height:1.9;margin:18px 0">Switch roles to follow an application from submission to decision. Changes are saved in this browser. Reset the workspace to restore the original sample data.</p>${btn('Switch workspace',`role:${state.role==='sme'?'lender':'sme'}`,'arrows','full')}${btn('Reset demonstration','confirm-reset','settings','full ghost')}<p class="tiny muted" style="line-height:1.8;margin-top:18px">This prototype does not connect to banks, process payments or provide live lending decisions.</p></div></section></div>`}
function pageContent(){return ({overview,transactions,marketplace,businesses,applications,suppliers:supplierPage,profile,portfolio,settings}[state.page]||overview)()}
function filterResults(){const q=state.query.toLowerCase(),a=state.advanced;let rows=[];if(state.page==='transactions'){rows=state.transactions.filter(t=>(state.filter==='all'||t.type===state.filter||t.method===state.filter)&&searchable([t.counterparty,t.category,t.id]).includes(q));$('#results').innerHTML=transactionTable(rows)}else if(state.page==='marketplace'){rows=D.lenders.filter(l=>BBFilters.providerMatches(l,{query:q,type:state.filter,category:state.creditCategory,...a})).sort((a,b)=>state.sort==='rate'?a.rate-b.rate:state.sort==='max'?b.max-a.max:state.sort==='speed'?a.speedHours-b.speedHours:b.match-a.match);$('#results').innerHTML=rows.length?rows.map(l=>lenderCard(l,true)).join(''):empty('No lenders match these filters','Change the amount, annual rate or decision time to see more options.','search',btn('Reset filters','reset-filters','filter','primary'));if($('#sort-input'))$('#sort-input').value=state.sort}else if(state.page==='businesses'){rows=D.businesses.filter(b=>BBFilters.vendorMatches(b,{query:q,sector:state.filter,category:state.creditCategory,minScore:state.risk==='all'?'':state.risk,...a},D.lenders)).sort((a,b)=>state.vendorSort==='revenue'?b.revenue-a.revenue:state.vendorSort==='requested'?b.requested-a.requested:state.vendorSort==='growth'?b.growth-a.growth:b.score-a.score);$('#results').innerHTML=rows.length?rows.map(b=>businessCard(b)).join(''):empty('No vendors match these filters','Try a different sector, term or financial threshold.','search',btn('Reset filters','reset-filters','filter','primary'));if($('#vendor-sort'))$('#vendor-sort').value=state.vendorSort||'score'}else if(state.page==='applications'){rows=myApps().filter(x=>(state.filter==='all'||x.status===state.filter)&&searchable([x.id,business(x.businessId).name,lender(x.lenderId).name,x.purpose]).includes(q));$('#results').innerHTML=applicationTable(rows)}if($('#results-count'))$('#results-count').textContent=`${rows.length} ${state.page==='marketplace'?(rows.length===1?'lender':'lenders'):state.page==='businesses'?(rows.length===1?'vendor':'vendors'):(rows.length===1?'transaction':'transactions')} found`;if($('#filter-input'))$('#filter-input').value=state.filter;if($('#risk-input'))$('#risk-input').value=state.risk||'all';const fields={'amount-filter':'amount','rate-filter':'rate','speed-filter':'speed','term-filter':'term','collateral-filter':'collateral','revenue-filter':'minRevenue','vendor-amount-filter':'maxAmount','trading-filter':'minTrading','payments-filter':'minPayments'};for(const [id,key] of Object.entries(fields))if($('#'+id))$('#'+id).value=a[key]||(['term','collateral'].includes(key)?'all':'');}

let lastFocused=null;
function modal(title,subtitle,body,footer='',wide=false){lastFocused=document.activeElement;$('#overlay').innerHTML=`<div class="modal-shade"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="iconbtn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay input:not([type="checkbox"]), #overlay select, #overlay button')?.focus(),20)}
function close(){const trigger=lastFocused;$('#overlay').innerHTML='';document.body.style.overflow='';trigger?.isConnected&&trigger.focus();}
function lenderDetail(id){const l=lender(id);modal(l.name,l.type,`<div class="offer-banner"><div class="eyebrow" style="color:#8eafe5;margin-bottom:8px">Indicative annual rate</div><div class="number" style="font-size:37px">${l.rate.toFixed(1)}%</div><p>${l.description}</p></div>${detail('Funding available',`${money(l.min)} to ${money(l.max)}`)}${detail('Repayment term',l.term.replace(/[–-]/g,' to '))}${detail('Typical decision',l.decision)}${detail('Profile match',`${l.match}% · Illustrative`)}${detail('Security',l.collateral)}${detail('Arrangement fee',l.fee+'%')}${detail('Minimum trading history',l.minTradingMonths+' months')}<div class="summary-list" style="gap:12px;margin-top:20px">${l.features.map(f=>`<div class="checkline">${icon('check')}${f}</div>`).join('')}</div><p class="tiny muted" style="line-height:1.8;margin-top:22px">Sample provider and indicative terms. Final rates, fees and eligibility would be confirmed by the provider. Submitting a demo application does not create a credit agreement.</p>`,btn('Close','close','','ghost')+btn(state.role==='sme'?'Start application':'View as vendor',state.role==='sme'?`apply:${id}`:`role:sme`,'arrow','primary'))}
function startApply(id){const l=lender(id);const terms=l.type==='Instant credit'?['1 month','3 months','6 months','12 months']:l.type==='Long term loan'?['24 months','36 months','60 months','84 months']:l.type==='Trade finance'?['3 months','6 months','12 months','18 months']:l.type==='Merchant finance'?['3 months','6 months','12 months']:l.type==='Invoice finance'?['30 days','60 days','90 days','120 days']:l.type==='Supplier credit'?['30 days','60 days','90 days']:l.type==='Credit line'?['Revolving']:l.type==='Working capital'?['6 months','12 months','24 months']:l.type==='Equipment finance'?['12 months','24 months','36 months','60 months']:['12 months','24 months','36 months'];modal('Apply for business finance',`Step 1 of 2 · ${l.name}`,`<div class="stepper"><span class="on"></span><span></span></div><form id="apply-form"><div class="field"><label for="amount">Funding amount (฿)</label><input id="amount" name="amount" type="number" min="${l.min}" max="${l.max}" step="100" value="${Math.min(l.max,Math.max(l.min,250000))}" required><small>Available from ${money(l.min)} to ${money(l.max)}</small></div><div class="field-grid"><div class="field"><label for="purpose">Purpose of finance</label><select id="purpose" name="purpose"><option>Equipment & expansion</option><option>Working capital</option><option>Inventory purchase</option><option>Supplier payments</option><option>Invoice funding</option></select></div><div class="field"><label for="term">Preferred term</label><select id="term" name="term">${terms.map(t=>`<option>${t}</option>`).join('')}</select></div></div><div class="field"><label for="notes">Additional information</label><textarea id="notes" name="notes" maxlength="600" placeholder="Tell the provider what this funding will support"></textarea></div><input type="hidden" name="lenderId" value="${id}"></form>`,btn('Cancel','close','','ghost')+'<button class="btn primary" type="submit" form="apply-form">Review application '+icon('arrow')+'</button>')}
let pendingApplication=null;
function reviewApply(values){pendingApplication=values;const l=lender(values.lenderId);modal('Review your application',`Step 2 of 2 · ${l.name}`,`<div class="stepper"><span class="on"></span><span class="on"></span></div><div class="offer-banner"><h3>${money(Number(values.amount))}</h3><p>${esc(values.purpose)} · ${esc(values.term)}</p></div>${detail('Business',esc(state.business.name))}${detail('Provider',l.name)}${detail('Indicative annual rate',l.rate+'%')}${detail('Information shared',[state.sharing.profile?'Business profile':'',state.sharing.transactions?'Transactions':'',state.sharing.documents?'Sample documents':''].filter(Boolean).join(', ')||'No optional data selected')}<form id="submit-application"><label class="checkbox" style="margin-top:20px"><input type="checkbox" required><span>I agree to share the selected information with ${l.name} for this demo application. I understand no real credit request is submitted.</span></label></form>`,btn('Back',`apply:${l.id}`,'','ghost')+'<button class="btn primary" type="submit" form="submit-application">Submit application '+icon('arrow')+'</button>')}
function submitApplication(){const v=pendingApplication;if(!v)return;const id='BB-'+String(Date.now()).slice(-6);state.applications.unshift({id,businessId:'bloom',lenderId:v.lenderId,amount:Number(v.amount),purpose:v.purpose,term:v.term,notes:v.notes,status:'Under review',date:'2026-11-17',shared:{...state.sharing}});persist();state.page='applications';render();pendingApplication=null;modal('Application submitted','Your request is ready for review.',`<div class="success-content"><div class="big-success">${icon('check')}</div><h2>Your application is ready for review.</h2><p>${lender(v.lenderId).name} can now review your application for ${money(Number(v.amount))}.<br>Reference ${id}</p><p style="margin-top:18px">Switch to the Siam Capital lender workspace to review applications sent to Siam Capital.</p></div>`,btn('View applications','close','arrow','primary'))}
function applicationDetail(id){const a=state.applications.find(a=>a.id===id);if(!a)return;const l=lender(a.lenderId),b=business(a.businessId),rate=a.offerRate||l.rate,term=Number.parseInt(a.offerTerm||a.term||'24');let actions=btn('Close','close','','ghost');const isL=state.role==='lender';if(isL&&['Under review','Information requested'].includes(a.status))actions+=btn('Request information',`request-info:${id}`,'','ghost')+btn('Make an offer',`make-offer:${id}`,'arrow','primary');else if(!isL&&a.status==='Offer received')actions+=btn('Decline offer',`decline:${id}`,'','ghost')+btn('Accept offer',`accept-confirm:${id}`,'check','primary');else if(!isL&&a.status==='Under review')actions+=btn('Withdraw application',`withdraw:${id}`,'','ghost');else if(!isL&&a.status==='Information requested')actions+=btn('Provide information',`provide-info:${id}`,'file','primary');modal(isL?esc(b.name):l.name,`Application ${a.id} · ${date(a.date)}`,`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px">${statusTag(a.status)}<button class="textbtn" data-action="business:${b.id}">View business profile ${icon('arrow')}</button></div><div class="offer-banner"><span class="tiny muted">Requested amount</span><h3 style="font-size:28px;margin-top:8px">${money(a.amount)}</h3><p>${esc(a.purpose)}</p></div>${detail('Business',esc(b.name))}${detail('Credit provider',l.name)}${detail('Purpose',esc(a.purpose))}${detail('Status',a.status)}${['Offer received','Accepted','Approved'].includes(a.status)?`${detail('Offered annual rate',rate+'%')}${detail('Repayment term',term+' months')}${detail('Estimated monthly repayment',money(payment(a.amount,rate,term),2))}<p class="tiny muted" style="line-height:1.8;margin-top:13px">Repayment estimate assumes a fixed rate with monthly amortisation and excludes fees. All offer terms are illustrative.</p>`:''}${a.notes?`<div class="notice" style="margin:20px 0 0">${icon('file')}${esc(a.notes)}</div>`:''}${a.infoRequest?`<div class="notice" style="margin:20px 0 0">${icon('info')}${esc(a.infoRequest)}</div>`:''}${a.response?`<div class="notice" style="margin:14px 0 0">${icon('file')}Business response: ${esc(a.response)}</div>`:''}`,actions)}
function payment(amount,rate,months){const r=rate/1200;return r?amount*r/(1-Math.pow(1+r,-months)):amount/months}
function makeOffer(id){const a=state.applications.find(a=>a.id===id);modal('Create a funding offer',`${business(a.businessId).name} · ${a.id}`,`<form id="offer-form"><input type="hidden" name="id" value="${id}"><div class="field"><label for="offer-amount">Funding amount (฿)</label><input id="offer-amount" value="${a.amount}" readonly><small>The offer covers the requested amount.</small></div><div class="field-grid"><div class="field"><label for="offer-rate">Annual interest rate (%)</label><input id="offer-rate" name="rate" type="number" min="0.1" max="49.9" step="0.1" value="7.9" required></div><div class="field"><label for="offer-term">Repayment term</label><select id="offer-term" name="term"><option value="12">12 months</option><option value="24" selected>24 months</option><option value="36">36 months</option></select></div></div><div class="field"><label for="offer-note">Offer notes</label><textarea name="notes" id="offer-note" placeholder="Any conditions the business should review" maxlength="600"></textarea></div><div class="notice">${icon('info')}This sends an illustrative offer to the business workspace. No funds or contracts are involved.</div></form>`,btn('Cancel','close','','ghost')+'<button class="btn primary" type="submit" form="offer-form">Send offer '+icon('arrow')+'</button>')}
let businessTab='overview',openBusinessId='bloom';
function businessDetail(id,tab='overview'){businessTab=tab;openBusinessId=id;const b=business(id);const permitted=state.role==='sme'||b.sharedDemo||state.applications.some(a=>a.businessId===id&&a.lenderId==='northstar');const isBloom=id==='bloom';const sharing=isBloom?state.sharing:{profile:true,transactions:permitted,documents:permitted};let body='';if(tab==='overview')body=`<div class="stats">${stat('Monthly revenue',money(b.revenue),'','Illustrative figure','chart')}${stat('Funding requested',money(b.requested),'','Business requirement','bank')}${stat('Credit readiness',b.score+' / 100','','Illustrative assessment','shield')}${stat('Revenue growth',b.growth+'%','','Compared with last month','up')}</div><div class="two-col"><div><h3 style="margin-bottom:12px">Business details</h3><p class="small muted" style="line-height:1.9;margin-bottom:14px">${sharing.profile?esc(b.description):'This business has disabled detailed profile sharing. Public directory figures remain visible.'}</p>${detail('Sector',esc(b.sector))}${detail('Location',esc(b.location))}${detail('Verification',b.verified?'Complete':'In progress')}${detail('Data access',permitted?'Shared sample records':'Profile preview only')}${detail('Payment performance',b.paymentPerformance+'% on time')}${detail('Debt service coverage',b.debtServiceCoverage+'×')}${detail('Operating margin',b.netMargin+'%')}${detail('Trading history',b.tradingMonths+' months')}${detail('Finance requested',esc(b.fundingType||'Business loan'))}</div><div><h3 style="margin-bottom:18px">Financial overview</h3><div class="summary-list"><div class="summary-item">${icon('chart')}<div><h4>Revenue trend</h4><p>Illustrative monthly revenue growth of ${b.growth}%.</p></div></div><div class="summary-item">${icon('arrows')}<div><h4>Trading activity</h4><p>${isBloom?state.transactions.length:'24'} recorded transactions in the demonstration period.</p></div></div><div class="summary-item">${icon('shield')}<div><h4>Readiness assessment</h4><p>This sample score helps illustrate a review. It is not a credit bureau score.</p></div></div></div></div></div>`;else if(tab==='cashflow')body=sharing.transactions&&permitted?chart('Business cash flow',isBloom?'Illustrative monthly history for Siam Pantry':'Illustrative financial history for this profile',b.revenue/D.business.revenue):empty('Financial records restricted','Detailed financial records are shared with selected providers.','lock');else if(tab==='transactions')body=sharing.transactions&&permitted?(isBloom?transactionTable(state.transactions,false):`<div class="notice">${icon('info')}These transactions are sample records scaled for this business. They do not represent actual activity.</div>${transactionTable(D.transactions.slice(0,7).map(t=>({...t,counterparty:t.type==='income'?'Customer payment':'Business expense',amount:Math.round(t.amount*b.revenue/D.business.revenue)})),false)}`):empty('Transaction access restricted','The business has not shared transaction history with this provider.','lock');else body=sharing.documents&&permitted?documents(id):empty('Document access restricted','Documents are available when the business shares them with your organisation.','lock');modal(esc(b.name),`${esc(b.sector)} · ${esc(b.location)}`,`<div class="tabs">${[['overview','Overview'],['cashflow','Cash flow'],['transactions','Transactions'],['documents','Documents']].map(([k,v])=>`<button data-action="business-tab:${k}" class="${tab===k?'selected':''}">${v}</button>`).join('')}</div>${body}`,btn('Close','close','','ghost')+(state.role==='lender'?btn('View applications',`business-apps:${id}`,'arrow','primary'):''),true)}
function addTransaction(){modal('Add a transaction','Record a payment received or a business expense.',`<form id="transaction-form"><div class="field-grid"><div class="field"><label for="tx-type">Transaction type</label><select id="tx-type" name="type"><option value="income">Money in</option><option value="expense">Money out</option></select></div><div class="field"><label for="tx-amount">Amount (฿)</label><input id="tx-amount" name="amount" type="number" min="0.01" max="10000000" step="0.01" required placeholder="0.00"></div></div><div class="field"><label for="tx-name">Customer or supplier</label><input id="tx-name" name="counterparty" required maxlength="80" placeholder="Business or payment name"></div><div class="field-grid"><div class="field"><label for="tx-date">Date</label><input id="tx-date" name="date" type="date" value="2026-11-17" max="2026-11-17" min="2020-01-01" required></div><div class="field"><label for="tx-method">Payment method</label><select id="tx-method" name="method"><option>Cash</option><option>Card</option><option>Bank transfer</option></select></div></div><div class="field"><label for="tx-category">Category</label><select id="tx-category" name="category"><option>Sales</option><option>Wholesale</option><option>Catering</option><option>Supplies</option><option>Payroll</option><option>Rent</option><option>Utilities</option><option>Other</option></select></div><p class="tiny muted">This records a transaction in the demo. It does not process a payment.</p></form>`,btn('Cancel','close','','ghost')+'<button class="btn primary" type="submit" form="transaction-form">Save transaction '+icon('check')+'</button>')}

function compareVendors(){const bs=D.businesses.filter(b=>state.vendorCompare.includes(b.id));if(bs.length<2){toast('Select at least two vendors to compare.');return}modal('Compare vendors','Shared sample financial records, side by side.',`<div class="table-wrap"><table><thead><tr><th>Business metric</th>${bs.map(b=>`<th>${esc(b.name)}</th>`).join('')}</tr></thead><tbody>${[['Monthly revenue',b=>money(b.revenue)],['Funding requested',b=>money(b.requested)],['Finance product',b=>b.fundingType],['Readiness score',b=>b.score+' / 100'],['On time payments',b=>b.paymentPerformance+'%'],['Debt service coverage',b=>b.debtServiceCoverage+'×'],['Operating margin',b=>b.netMargin+'%'],['Trading history',b=>b.tradingMonths+' months'],['Preferred term',b=>b.termPreference==='short'?'Up to 12 months':'Over 12 months']].map(([k,fn])=>`<tr><td>${k}</td>${bs.map(b=>`<td><strong>${esc(fn(b))}</strong></td>`).join('')}</tr>`).join('')}<tr><td></td>${bs.map(b=>`<td>${btn('Review vendor',`business:${b.id}`,'arrow','sm primary')}</td>`).join('')}</tr></tbody></table></div><p class="tiny muted" style="margin-top:20px;line-height:1.8">Fictional vendor records. These figures do not represent a credit bureau assessment.</p>`,btn('Close','close','','ghost'),true)}

function compare(){const ls=D.lenders.filter(l=>state.compare.includes(l.id));if(ls.length<2){toast('Select at least two providers to compare.');return}modal('Compare credit providers','Review indicative terms side by side.',`<div class="table-wrap"><table><thead><tr><th>Provider</th>${ls.map(l=>`<th>${l.name}</th>`).join('')}</tr></thead><tbody>${[['Annual rate',l=>l.rate+'%'],['Funding range',l=>short(l.min)+' to '+short(l.max)],['Term',l=>l.term.replace(/[–-]/g,' to ')],['Decision',l=>l.decision],['Funding type',l=>l.type],['Security',l=>l.collateral],['Arrangement fee',l=>l.fee+'%'],['Minimum trading',l=>l.minTradingMonths+' months'],['Profile match',l=>l.match+'%']].map(([k,fn])=>`<tr><td>${k}</td>${ls.map(l=>`<td><strong>${fn(l)}</strong></td>`).join('')}</tr>`).join('')}<tr><td></td>${ls.map(l=>`<td>${btn('View option',`lender:${l.id}`,'arrow','sm primary')}</td>`).join('')}</tr></tbody></table></div><p class="tiny muted" style="line-height:1.8;margin-top:20px">All providers and terms are fictional. The final cost of credit would depend on the provider assessment and applicable fees.</p>`,btn('Close','close','','ghost'),true)}
function documentPreview(i,businessId='bloom'){const docBusiness=business(businessId);const names=['Business registration','Bank statements','Management accounts'];modal(names[i],'Sample document preview',`<div style="padding:25px;border:1px solid #30435f;border-radius:8px;background:#0d1828"><div class="eyebrow muted" style="margin-bottom:22px">Bahtbridge · Sample document</div><h2>${names[i]} · ${esc(docBusiness.name)}</h2><p class="small muted" style="line-height:1.9;margin-top:14px">Prepared for the Bahtbridge demonstration. This is a sample preview and is not an official record.</p>${detail('Business',esc(docBusiness.name))}${detail('Reporting period','November 2026')}${i===0?detail('Demo registration',docBusiness.registration||'DEMO SAMPLE')+detail('Status','Sample verified record'):i===1?detail('Opening balance',money(Math.round(110400*docBusiness.revenue/486500)))+detail('Recorded monthly income',money(docBusiness.revenue))+detail('Recorded monthly expenses',money(docBusiness.monthlyExpenses||Math.round(312400*docBusiness.revenue/486500)))+detail('Closing balance',money(Math.round(110400*docBusiness.revenue/486500)+docBusiness.revenue-(docBusiness.monthlyExpenses||Math.round(312400*docBusiness.revenue/486500)))):detail('Revenue',money(docBusiness.revenue))+detail('Operating expenses',money(docBusiness.monthlyExpenses||Math.round(312400*docBusiness.revenue/486500)))+detail('Operating surplus',money(docBusiness.revenue-(docBusiness.monthlyExpenses||Math.round(312400*docBusiness.revenue/486500))))}</div>`,btn('Close','close','','ghost')+btn('Download sample',`download-document:${i}:${businessId}`,'download','primary'))}
function exportCSV(filename,headers,rows){const csv=[headers,...rows].map(row=>row.map(x=>`"${String(typeof x==='string'&&window.BBLocale?.language==='th'?window.BBLocale.t(x):(x??'')).replace(/"/g,'""')}"`).join(',')).join('\r\n');download(filename,csv,'text/csv');toast('Your export is ready. All figures are demonstration data.');}
function download(filename,content,type='text/plain'){const url=URL.createObjectURL(new Blob([type==='text/csv'?'\uFEFF':'',content],{type:type+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function confirmAction(title,desc,action,label){modal(title,'Demonstration workspace',`<p class="small muted" style="line-height:1.9">${desc}</p>`,btn('Cancel','close','','ghost')+btn(label,action,'check','primary'))}
document.addEventListener('click',e=>{if(!window.BahtbridgeAccess.active)return;const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;const [key,...rest]=action.split(':');const id=rest.join(':');e.preventDefault();
if(key==='category'){state.creditCategory=id;render()}else if(key==='reset-filters'){state.query='';state.filter='all';state.risk='all';state.sort='match';state.vendorSort='score';state.creditCategory='all';state.advanced={};render()}else if(key==='compare-vendors')compareVendors();else if(key==='clear-vendors'){state.vendorCompare=[];render()}else if(key==='nav'){close();go(id)}else if(key==='role'){if(id===state.role)return;close();window.BahtbridgeAccess.open(id)}else if(key==='menu')$('.sidebar').classList.toggle('open');else if(key==='close')close();else if(key==='period'){state.period=id;if($('#overlay').innerHTML&&businessTab==='cashflow')businessDetail(openBusinessId,'cashflow');else render()}else if(key==='add-transaction')addTransaction();else if(key==='lender')lenderDetail(id);else if(key==='apply')startApply(id);else if(key==='compare')compare();else if(key==='clear-compare'){state.compare=[];render()}else if(key==='business')businessDetail(id);else if(key==='business-tab')businessDetail(openBusinessId,id);else if(key==='application')applicationDetail(id);else if(key==='make-offer')makeOffer(id);
else if(key==='accept-confirm')confirmAction('Accept this sample offer?','Accepting updates the business application and lender portfolio in this browser. No funds are transferred and no real agreement is created.',`accept:${id}`,'Accept sample offer');else if(['accept','decline','withdraw'].includes(key)){const a=state.applications.find(a=>a.id===id);a.status=key==='accept'?'Accepted':key==='decline'?'Declined':'Withdrawn';persist();close();render();toast(key==='accept'?'Sample offer accepted. The lender portfolio has been updated.':'Application updated.');}
else if(key==='request-info'||key==='provide-info'){modal(key==='request-info'?'Request more information':'Provide information',`Application ${id}`,`<form id="information-form"><input name="id" type="hidden" value="${id}"><input name="kind" type="hidden" value="${key}"><div class="field"><label for="information-text">${key==='request-info'?'What would you like the business to provide?':'Your response'}</label><textarea id="information-text" name="text" maxlength="1000" required placeholder="Enter the details"></textarea></div></form>`,btn('Cancel','close','','ghost')+'<button class="btn primary" type="submit" form="information-form">Send '+icon('arrow')+'</button>')}
else if(key==='business-apps'){close();state.page='applications';state.query=business(id).name;state.filter='all';render()}
else if(key==='document'){const [documentId,bizId]=id.split(':');documentPreview(Number(documentId),bizId||'bloom');}else if(key==='download-document'){const [docId,bizId]=id.split(':');const db=business(bizId||'bloom');const names=['Business registration','Bank statements','Management accounts'];download(`Bahtbridge_sample_${iSafe(docId)}.txt`,`BAHTBRIDGE DEMONSTRATION\n${names[Number(docId)]}\nBusiness: ${db.name}\nReporting period: November 2026\nThis is fictional sample data and is not an official document.\nSample registration: ${db.registration||'DEMO SAMPLE'}\nMonthly income: THB ${db.revenue}\nMonthly expenses: THB ${Math.round(312400*db.revenue/D.business.revenue)}\nClosing balance: THB ${Math.round(284500*db.revenue/D.business.revenue)}`);toast('Sample document downloaded.')}
else if(key==='supplier-credit'){go('marketplace');state.filter='Supplier credit';filterResults()}else if(key==='supplier'){const s=suppliers[Number(id)];modal(s.name,s.type,`${detail('Relationship','Active supplier')}${detail('Payment terms',s.terms)}${detail('Illustrative trading volume',money(s.volume))}${detail('Illustrative outstanding balance',money(s.outstanding,2))}${detail('Verification','Sample verified profile')}<div class="notice" style="margin-top:20px">${icon('info')}Supplier data and invoice balances are sample records.</div>`,btn('Close','close','','ghost')+(s.businessId&&state.role==='lender'?btn('View business profile',`business:${s.businessId}`,'arrow','primary'):state.role==='sme'?btn('Explore supplier credit','supplier-credit','arrow','primary'):''))}
else if(key==='edit-profile'){const b=state.business;modal('Edit business profile','Update the details providers see about your business.',`<form id="profile-form"><div class="field"><label for="profile-name">Business name</label><input name="name" id="profile-name" value="${esc(b.name)}" required maxlength="70"></div><div class="field-grid"><div class="field"><label for="profile-owner">Business owner</label><input name="owner" id="profile-owner" value="${esc(b.owner)}" required maxlength="60"></div><div class="field"><label for="profile-email">Business email</label><input name="email" id="profile-email" type="email" value="${esc(b.email)}" required></div></div><div class="field"><label for="profile-desc">Business description</label><textarea name="description" id="profile-desc" required maxlength="500">${esc(b.description)}</textarea></div><div class="field"><label for="profile-address">Address</label><input name="address" id="profile-address" value="${esc(b.address)}" required maxlength="150"></div></form>`,btn('Cancel','close','','ghost')+'<button class="btn primary" type="submit" form="profile-form">Save changes '+icon('check')+'</button>')}
else if(key==='edit-lender')modal('Lending criteria','Siam Capital · Demonstration profile',`<p class="small muted" style="line-height:1.9;margin-bottom:20px">Adjust the indicative rate shown to businesses in this session.</p><form id="lender-profile-form"><div class="field"><label for="provider-rate">Indicative annual rate (%)</label><input id="provider-rate" name="rate" type="number" min="0.1" max="49.9" step="0.1" required value="${D.lenders[0].rate}"></div><div class="field"><label for="provider-desc">Provider description</label><textarea id="provider-desc" name="description" required maxlength="500">${esc(D.lenders[0].description)}</textarea></div></form>`,btn('Cancel','close','','ghost')+'<button class="btn primary" type="submit" form="lender-profile-form">Save provider details</button>');
else if(key==='add-document')modal('Record a document','Add a document reference to the demo profile.',`<form id="document-form"><div class="field"><label for="document-name">Document name</label><input id="document-name" name="name" placeholder="For example, latest management accounts" maxlength="100" required><small>This prototype saves the document name only. No file is uploaded.</small></div></form>`,btn('Cancel','close','','ghost')+'<button class="btn primary" type="submit" form="document-form">Save document record</button>');
else if(key==='notifications'){const old=$('.notifications');if(old){old.remove();return}const a=myApps().find(a=>a.status==='Offer received');$('.topbar').insertAdjacentHTML('beforeend',`<div class="notifications"><div style="display:flex;justify-content:space-between"><h3>Notifications</h3><button class="iconbtn" data-action="notifications" aria-label="Close notifications">${icon('close')}</button></div>${a?`<p><strong>Funding offer available</strong>${lender(a.lenderId).name} has an offer for ${money(a.amount)}.<br><button class="textbtn" data-action="application:${a.id}">Review offer ${icon('arrow')}</button></p>`:`<p><strong>Your workspace is current</strong>Review recent applications for the latest updates.</p>`}<p><strong>Demonstration workspace</strong>Switch roles to explore both sides of Bahtbridge.</p></div>`)}
else if(key==='help')modal('Help & support','A guide to the Bahtbridge demonstration.',`<div class="summary-list">${[['arrows','Record business activity','Add cash, card and bank transaction records in Transactions. Export entries as a CSV file.'],['bank','Explore credit options','Compare fictional providers and submit an application from the business workspace.'],['users','Review as a provider','Switch to Credit provider to review Siam Capital applications, inspect shared data and send an offer.'],['shield','Manage your data','Use Settings to change business sharing permissions or reset the demonstration.']].map(([ic,t,p])=>`<div class="summary-item">${icon(ic)}<div><h4>${t}</h4><p>${p}</p></div></div>`).join('')}</div>`,btn('Got it','close','check','primary'));
else if(key==='confirm-reset')confirmAction('Reset the workspace?','This removes your saved transactions, applications, document records and profile changes from this browser, then restores the original demonstration data.','reset','Reset workspace');else if(key==='reset'){localStorage.removeItem('bahtbridge-v2');location.reload()}
else if(key==='export-transactions')exportCSV('Bahtbridge_transactions.csv',['Reference','Date','Type','Counterparty','Category','Payment method','Amount THB','Status'],state.transactions.map(t=>[t.id,t.date,t.type,t.counterparty,t.category,t.method,t.amount,t.status]));else if(key==='export-businesses')exportCSV('Bahtbridge_business_directory.csv',['Business','Sector','Location','Monthly revenue THB','Funding requested THB','Readiness score','Data'],D.businesses.map(b=>[b.name,b.sector,b.location,b.revenue,b.requested,b.score,'Fictional demo']));else if(key==='export-portfolio')exportCSV('Bahtbridge_portfolio.csv',['Application','Business','Amount THB','Status','Data'],myApps().filter(a=>['Approved','Accepted'].includes(a.status)).map(a=>[a.id,business(a.businessId).name,a.amount,a.status,'Fictional demo']));else if(key==='export-report')exportCSV('Bahtbridge_demo_report.csv',['Metric','Value','Data'],state.role==='sme'?[['Business',state.business.name,'Fictional demo'],['Monthly income THB',monthlyTotals().income,'Illustrative'],['Monthly expenses THB',monthlyTotals().expense,'Illustrative'],['Available balance THB',monthlyTotals().balance,'Illustrative'],['Credit readiness',82,'Illustrative'],['Applications',myApps().length,'Demo records']]:[['Provider','Siam Capital','Fictional demo'],['Applications',myApps().length,'Demo records'],['Approved funding THB',myApps().filter(a=>['Approved','Accepted'].includes(a.status)).reduce((s,a)=>s+a.amount,0),'Demo records']]);
});
function iSafe(s){return String(s).replace(/[^0-9]/g,'')}
document.addEventListener('input',e=>{if(!window.BahtbridgeAccess.active)return;if(e.target.id==='search-input'){state.query=e.target.value;filterResults()}if(e.target.id==='amount-filter'){state.advanced.amount=e.target.value;filterResults()}});
document.addEventListener('change',e=>{if(!window.BahtbridgeAccess.active)return;const filterKeys={'amount-filter':'amount','rate-filter':'rate','speed-filter':'speed','term-filter':'term','collateral-filter':'collateral','revenue-filter':'minRevenue','vendor-amount-filter':'maxAmount','trading-filter':'minTrading','payments-filter':'minPayments'};if(filterKeys[e.target.id]){state.advanced[filterKeys[e.target.id]]=e.target.value;filterResults()}if(e.target.id==='vendor-sort'){state.vendorSort=e.target.value;filterResults()}if(e.target.dataset.vendorCompare){const id=e.target.dataset.vendorCompare;if(e.target.checked){if(state.vendorCompare.length>=3){e.target.checked=false;toast('Compare up to three vendors.');return}state.vendorCompare.push(id)}else state.vendorCompare=state.vendorCompare.filter(v=>v!==id);state.compare=[];render()}if(e.target.id==='filter-input'){state.filter=e.target.value;filterResults()}if(e.target.id==='sort-input'){state.sort=e.target.value;filterResults()}if(e.target.id==='risk-input'){state.risk=e.target.value;filterResults()}if(e.target.dataset.compare){const id=e.target.dataset.compare;state.vendorCompare=[];if(e.target.checked){if(state.compare.length>=3){e.target.checked=false;toast('Compare up to three providers at a time.');return}state.compare.push(id)}else state.compare=state.compare.filter(x=>x!==id);render()}if(e.target.dataset.setting){state.sharing[e.target.dataset.setting]=e.target.checked;persist();toast('Sharing preferences saved.')}});
document.addEventListener('submit',e=>{if(!window.BahtbridgeAccess.active||e.target.id==='access-signin-form')return;e.preventDefault();const form=e.target,v=Object.fromEntries(new FormData(form));if(form.id==='transaction-form'){state.transactions.unshift({...v,amount:Number(v.amount),id:'TX-'+String(Date.now()).slice(-7),status:'Completed'});persist();close();render();toast('Transaction recorded. Your business activity has been updated.')}else if(form.id==='apply-form')reviewApply(v);else if(form.id==='submit-application')submitApplication();else if(form.id==='offer-form'){const a=state.applications.find(a=>a.id===v.id);a.status='Offer received';a.offerRate=Number(v.rate);a.offerTerm=Number(v.term);a.notes=v.notes||a.notes;persist();close();render();toast('Offer sent. Switch to the business workspace to review it.')}else if(form.id==='information-form'){const a=state.applications.find(a=>a.id===v.id);if(v.kind==='request-info'){a.status='Information requested';a.infoRequest=v.text}else{a.status='Under review';a.response=v.text}persist();close();render();toast('Application updated. Your message is available in the other workspace.')}else if(form.id==='profile-form'){Object.assign(state.business,v);persist();close();render();toast('Business profile updated.')}else if(form.id==='document-form'){state.documents=state.documents||[];state.documents.push({name:v.name});persist();close();render();toast('Document reference saved. No file has been uploaded.')}else if(form.id==='lender-profile-form'){D.lenders[0].rate=Number(v.rate);D.lenders[0].description=v.description;state.provider={rate:Number(v.rate),description:v.description};persist();close();render();toast('Provider details updated across both workspaces.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();$('.notifications')?.remove();$('.sidebar')?.classList.remove('open')}if(e.key==='Tab'&&$('#overlay .modal')){const els=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.type!=='hidden');if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-shade'))close();if(!e.target.closest('.notifications')&&!e.target.closest('[data-action="notifications"]'))$('.notifications')?.remove();if(!e.target.closest('.sidebar')&&!e.target.closest('.mobile-toggle'))$('.sidebar')?.classList.remove('open')});
if(state.provider)Object.assign(D.lenders[0],state.provider);
window.BahtbridgeAccess.onSignIn(role=>{state.role=role;state.page='overview';state.query='';state.filter='all';state.compare=[];state.vendorCompare=[];state.creditCategory='all';state.advanced={};state.risk='all';persist();render();});
render();
})();

